import type { ExpenseViewModel } from '../application/ExpenseViewModel'
import type { ExpensesGateway, FieldErrors, NewExpense, SubmitResult } from '../application/ExpensesGateway'

export class HttpExpensesGateway implements ExpensesGateway {
  async list(): Promise<ExpenseViewModel[]> {
    const response = await fetch('/api/expenses')
    if (!response.ok) throw new Error(`Could not load expenses (${response.status})`)
    return (await response.json()) as ExpenseViewModel[]
  }

  async submit(expense: NewExpense): Promise<SubmitResult> {
    const response = await fetch('/api/expenses', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(expense),
    })
    if (response.status === 422) {
      const body = (await response.json()) as { errors: FieldErrors }
      return { accepted: false, errors: body.errors }
    }
    if (!response.ok) throw new Error(`Could not submit the expense (${response.status})`)
    return { accepted: true, expense: (await response.json()) as ExpenseViewModel }
  }
}
