import { useCallback, useEffect, useState } from 'react'

import type { ExpenseViewModel } from '../../application/ExpenseViewModel'
import type { FieldErrors, NewExpense } from '../../application/ExpensesGateway'
import { useExpensesUseCases } from '../useExpensesUseCases/useExpensesUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpensesUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)

  useEffect(() => {
    let active = true
    listExpenses
      .execute()
      .then((items) => active && setExpenses(items))
      .catch((error: unknown) => active && setLoadError(error instanceof Error ? error.message : 'Could not load expenses'))
      .finally(() => active && setLoading(false))
    return () => {
      active = false
    }
  }, [listExpenses])

  const submit = useCallback(
    async (expense: NewExpense): Promise<FieldErrors> => {
      const result = await submitExpense.execute(expense)
      if (!result.accepted) return result.errors
      setExpenses((current) => [...current, result.expense])
      return {}
    },
    [submitExpense],
  )

  return { expenses, loading, loadError, submit }
}
